import React, { useState, useEffect } from 'react';
import { BrowserRouter as Router, Routes, Route, NavLink } from 'react-router-dom';
import ImportPage from './pages/ImportPage';
import MappingPage from './pages/MappingPage';
import MarkingPage from './pages/MarkingPage';
import ReportsPage from './pages/ReportsPage';
import LabelsPage from './pages/LabelsPage';
import Dashboard from './pages/Dashboard';
import axios from 'axios';

const API = process.env.REACT_APP_API || '';

export const api = axios.create({ baseURL: `${API}/api` });

const NAV = [
  { path: '/',         label: '📊 Dashboard'  },
  { path: '/import',   label: '📥 Import'     },
  { path: '/mapping',  label: '🔗 Mapping'    },
  { path: '/marking',  label: '✅ Marking'    },
  { path: '/reports',  label: '📋 Reports'  , component: ReportsPage  },
  { path: '/labels',   label: '🏷️ Labels'     },
];

const styles = {
  layout:   { display:'flex', minHeight:'100vh' },
  sidebar:  { width:200, background:'#1a3c5e', color:'#fff', padding:'0', display:'flex', flexDirection:'column' },
  logo:     { padding:'20px 16px', borderBottom:'1px solid #2a5a8a', fontWeight:700, fontSize:16, letterSpacing:0.5 },
  logoSub:  { fontSize:11, fontWeight:400, color:'#8ab4d0', marginTop:2 },
  nav:      { flex:1, paddingTop:8 },
  navLink:  { display:'block', padding:'10px 16px', color:'#b8d4e8', textDecoration:'none', fontSize:14, borderLeft:'3px solid transparent', transition:'all 0.15s' },
  navActive:{ color:'#fff', background:'#2a5a8a', borderLeft:'3px solid #4aade8' },
  main:     { flex:1, padding:'24px', overflowY:'auto' },
  card:     { background:'#fff', borderRadius:8, boxShadow:'0 1px 4px rgba(0,0,0,0.1)', padding:24, marginBottom:16 },
};

export const Card = ({ children, style }) => <div style={{...styles.card, ...style}}>{children}</div>;

export const Button = ({ children, onClick, variant='primary', disabled, style, size='md' }) => {
  const base = {
    padding: size==='sm' ? '5px 12px' : '8px 18px',
    fontSize: size==='sm' ? 12 : 14,
    border:'none', borderRadius:6, cursor: disabled ? 'not-allowed' : 'pointer',
    fontWeight:600, transition:'all 0.15s', opacity: disabled ? 0.6 : 1, ...style
  };
  const variants = {
    primary:  { background:'#1a3c5e', color:'#fff' },
    success:  { background:'#1a7a4a', color:'#fff' },
    danger:   { background:'#c0392b', color:'#fff' },
    outline:  { background:'transparent', color:'#1a3c5e', border:'1.5px solid #1a3c5e' },
    warning:  { background:'#e67e22', color:'#fff' },
    gray:     { background:'#6c757d', color:'#fff' },
  };
  return <button style={{...base,...variants[variant]}} onClick={onClick} disabled={disabled}>{children}</button>;
};

export const Input = ({ label, value, onChange, type='text', placeholder, style }) => (
  <div style={{ marginBottom:14, ...style }}>
    {label && <label style={{ display:'block', fontSize:12, fontWeight:600, color:'#444', marginBottom:4 }}>{label}</label>}
    <input
      type={type}
      value={value || ''}
      onChange={e => onChange(e.target.value)}
      placeholder={placeholder}
      style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:14, outline:'none' }}
    />
  </div>
);

export const Select = ({ label, value, onChange, options = [], placeholder, style }) => (
  <div style={{ marginBottom:14, ...style }}>
    {label && <label style={{ display:'block', fontSize:12, fontWeight:600, color:'#444', marginBottom:4 }}>{label}</label>}
    <select
      value={value || ''}
      onChange={e => onChange(e.target.value)}
      style={{ width:'100%', padding:'7px 10px', border:'1.5px solid #cbd5e0', borderRadius:6, fontSize:14, background:'#fff' }}
    >
      {placeholder && <option value="">{placeholder}</option>}
      {options.map(o => (
        <option key={o.value || o} value={o.value || o}>{o.label || o}</option>
      ))}
    </select>
  </div>
);

export const Table = ({ cols, rows, emptyMsg = 'No data' }) => (
  <div style={{ overflowX:'auto' }}>
    <table style={{ width:'100%', borderCollapse:'collapse', fontSize:13 }}>
      <thead>
        <tr style={{ background:'#f0f4f8' }}>
          {cols.map(c => (
            <th key={c.key || c.label} style={{ padding:'8px 10px', textAlign:'left', fontWeight:600, color:'#444', borderBottom:'2px solid #e2e8f0', whiteSpace:'nowrap' }}>
              {c.label}
            </th>
          ))}
        </tr>
      </thead>
      <tbody>
        {rows.length === 0 ? (
          <tr><td colSpan={cols.length} style={{ padding:24, textAlign:'center', color:'#999' }}>{emptyMsg}</td></tr>
        ) : rows.map((row, i) => (
          <tr key={i} style={{ borderBottom:'1px solid #f0f4f8', background: i%2===0?'#fff':'#fafbfc' }}>
            {cols.map(c => (
              <td key={c.key || c.label} style={{ padding:'7px 10px', color:'#333', whiteSpace:'nowrap' }}>
                {c.render ? c.render(row) : row[c.key]}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  </div>
);

export const Badge = ({ children, color = 'blue' }) => {
  const colors = {
    blue:   { background:'#dbeafe', color:'#1e40af' },
    green:  { background:'#dcfce7', color:'#166534' },
    red:    { background:'#fee2e2', color:'#991b1b' },
    yellow: { background:'#fef9c3', color:'#854d0e' },
    gray:   { background:'#f1f5f9', color:'#475569' },
  };
  return (
    <span style={{ ...colors[color], padding:'2px 8px', borderRadius:99, fontSize:11, fontWeight:600 }}>
      {children}
    </span>
  );
};

export const Alert = ({ msg, type = 'info' }) => {
  if (!msg) return null;
  const colors = { info:'#dbeafe', success:'#dcfce7', error:'#fee2e2', warning:'#fef9c3' };
  const text   = { info:'#1e40af', success:'#166534', error:'#991b1b', warning:'#854d0e' };
  return (
    <div style={{ background:colors[type], color:text[type], padding:'10px 14px', borderRadius:6, fontSize:13, marginBottom:12 }}>
      {msg}
    </div>
  );
};

